"""Semantic conventions for the channel-neutral ``rasa.turn.*`` metrics.

Single source of truth for the turn metric names and metric attribute keys.
Attribute values are short developer-controlled tokens (the enums in
:mod:`rasa.tracing.turn.attribute_values`); IDs and content are never metric
attributes.

Note on the name ``rasa.turn``: it is used here as the OTel *meter* name and
by the genai tracing work (ENG-3003) as a *span* name. These are different
OTel signals; the overlap is intentional, not a conflict.
"""

TURN_METER_NAME = "rasa.turn"

# Histogram (seconds): turn processing start to its terminal state.
METRIC_TURN_DURATION = "rasa.turn.duration"
# Histogram (seconds): input trigger to the first output in the expected modality.
METRIC_TURN_TIME_TO_FIRST_OUTPUT = "rasa.turn.time_to_first_output"

METRIC_ATTR_TURN_INPUT_TYPE = "rasa.turn.input.type"
METRIC_ATTR_TURN_OUTPUT_TYPE = "rasa.turn.output.type"
METRIC_ATTR_TURN_OUTCOME = "rasa.turn.outcome"
